#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdatomic.h>
#include <pthread.h>
#include <unistd.h>
#ifdef __APPLE__
#include <sys/sysctl.h>
#endif

#if defined(__aarch64__) || defined(_M_ARM64)
#include <arm_neon.h>
#define ARCH_NEON 1
#elif defined(__x86_64__) || defined(__i386__)
#include <immintrin.h>
#define ARCH_X86 1
#endif

#if defined(ARCH_NEON)
#define MR 8
#define NR 12
#define KC 512
#define MC 128
#define NC 1536
#elif defined(ARCH_X86)
#define MR 6
#define NR 16
#define KC 256
#define MC 120
#define NC 1024
#else
#define MR 4
#define NR 8
#define KC 256
#define MC 128
#define NC 1024
#endif

typedef void (*kern_t)(int kc, const float *a, const float *b, float *c, long ldc, int acc);

/* Portable reference micro-kernel: C[MRxNR] (+)= Ap * Bp */
static void kern_ref(int kc, const float *a, const float *b, float *c, long ldc, int acc)
{
    float t[MR][NR];
    for (int i = 0; i < MR; i++)
        for (int j = 0; j < NR; j++) t[i][j] = 0.0f;
    for (int k = 0; k < kc; k++) {
        const float *ak = a + (long)k * MR, *bk = b + (long)k * NR;
        for (int i = 0; i < MR; i++) {
            float ai = ak[i];
            for (int j = 0; j < NR; j++) t[i][j] += ai * bk[j];
        }
    }
    for (int i = 0; i < MR; i++) {
        float *ci = c + i * ldc;
        if (acc) for (int j = 0; j < NR; j++) ci[j] += t[i][j];
        else     for (int j = 0; j < NR; j++) ci[j] = t[i][j];
    }
}

#if defined(ARCH_NEON)
static void kern_neon(int kc, const float *a, const float *b, float *c, long ldc, int acc)
{
    float32x4_t c00 = vdupq_n_f32(0), c01 = c00, c02 = c00;
    float32x4_t c10 = c00, c11 = c00, c12 = c00;
    float32x4_t c20 = c00, c21 = c00, c22 = c00;
    float32x4_t c30 = c00, c31 = c00, c32 = c00;
    float32x4_t c40 = c00, c41 = c00, c42 = c00;
    float32x4_t c50 = c00, c51 = c00, c52 = c00;
    float32x4_t c60 = c00, c61 = c00, c62 = c00;
    float32x4_t c70 = c00, c71 = c00, c72 = c00;

#define NROW(r, av, l)                               \
    c##r##0 = vfmaq_laneq_f32(c##r##0, b0, av, l);   \
    c##r##1 = vfmaq_laneq_f32(c##r##1, b1, av, l);   \
    c##r##2 = vfmaq_laneq_f32(c##r##2, b2, av, l);

    for (int k = 0; k < kc; k++) {
        float32x4_t a0 = vld1q_f32(a), a1 = vld1q_f32(a + 4);
        float32x4_t b0 = vld1q_f32(b), b1 = vld1q_f32(b + 4), b2 = vld1q_f32(b + 8);
        NROW(0, a0, 0) NROW(1, a0, 1) NROW(2, a0, 2) NROW(3, a0, 3)
        NROW(4, a1, 0) NROW(5, a1, 1) NROW(6, a1, 2) NROW(7, a1, 3)
        a += MR;
        b += NR;
    }
#undef NROW

#define NSTORE(r)                                                        \
    {                                                                    \
        float *cr = c + r * ldc;                                         \
        if (acc) {                                                       \
            c##r##0 = vaddq_f32(c##r##0, vld1q_f32(cr));                 \
            c##r##1 = vaddq_f32(c##r##1, vld1q_f32(cr + 4));             \
            c##r##2 = vaddq_f32(c##r##2, vld1q_f32(cr + 8));             \
        }                                                                \
        vst1q_f32(cr, c##r##0);                                          \
        vst1q_f32(cr + 4, c##r##1);                                      \
        vst1q_f32(cr + 8, c##r##2);                                      \
    }
    NSTORE(0) NSTORE(1) NSTORE(2) NSTORE(3)
    NSTORE(4) NSTORE(5) NSTORE(6) NSTORE(7)
#undef NSTORE
}
#endif

#if defined(ARCH_X86)
__attribute__((target("avx2,fma")))
static void kern_avx2(int kc, const float *a, const float *b, float *c, long ldc, int acc)
{
    __m256 c00 = _mm256_setzero_ps(), c01 = c00;
    __m256 c10 = c00, c11 = c00, c20 = c00, c21 = c00;
    __m256 c30 = c00, c31 = c00, c40 = c00, c41 = c00;
    __m256 c50 = c00, c51 = c00;

#define XROW(r)                                          \
    {                                                    \
        __m256 ar = _mm256_broadcast_ss(a + r);          \
        c##r##0 = _mm256_fmadd_ps(ar, b0, c##r##0);      \
        c##r##1 = _mm256_fmadd_ps(ar, b1, c##r##1);      \
    }
    for (int k = 0; k < kc; k++) {
        __m256 b0 = _mm256_loadu_ps(b), b1 = _mm256_loadu_ps(b + 8);
        XROW(0) XROW(1) XROW(2) XROW(3) XROW(4) XROW(5)
        a += MR;
        b += NR;
    }
#undef XROW

#define XSTORE(r)                                                        \
    {                                                                    \
        float *cr = c + r * ldc;                                         \
        if (acc) {                                                       \
            c##r##0 = _mm256_add_ps(c##r##0, _mm256_loadu_ps(cr));       \
            c##r##1 = _mm256_add_ps(c##r##1, _mm256_loadu_ps(cr + 8));   \
        }                                                                \
        _mm256_storeu_ps(cr, c##r##0);                                   \
        _mm256_storeu_ps(cr + 8, c##r##1);                               \
    }
    XSTORE(0) XSTORE(1) XSTORE(2) XSTORE(3) XSTORE(4) XSTORE(5)
#undef XSTORE
}
#endif

static kern_t pick_kernel(void)
{
#if defined(ARCH_NEON)
    return kern_neon;
#elif defined(ARCH_X86)
    __builtin_cpu_init();
    if (__builtin_cpu_supports("avx2") && __builtin_cpu_supports("fma"))
        return kern_avx2;
    return kern_ref;
#else
    return kern_ref;
#endif
}

/* Pack an mc x kc block of A into MR-row panels, zero-padding short panels. */
static void pack_a(const float *A, long n, int ic, int pc, int mc, int kc, float *dst)
{
    for (int ir = 0; ir < mc; ir += MR) {
        int mr = mc - ir < MR ? mc - ir : MR;
        for (int i = 0; i < mr; i++) {
            const float *src = A + (long)(ic + ir + i) * n + pc;
            float *d = dst + i;
            for (int k = 0; k < kc; k++) d[(long)k * MR] = src[k];
        }
        for (int i = mr; i < MR; i++) {
            float *d = dst + i;
            for (int k = 0; k < kc; k++) d[(long)k * MR] = 0.0f;
        }
        dst += (long)kc * MR;
    }
}

/* Pack a kc x nc block of B into NR-column panels, zero-padding short panels. */
static void pack_b(const float *B, long n, int pc, int jc, int kc, int nc, float *dst)
{
    for (int jr = 0; jr < nc; jr += NR) {
        int nr = nc - jr < NR ? nc - jr : NR;
        for (int k = 0; k < kc; k++) {
            const float *src = B + (long)(pc + k) * n + jc + jr;
            int j = 0;
            for (; j < nr; j++) dst[j] = src[j];
            for (; j < NR; j++) dst[j] = 0.0f;
            dst += NR;
        }
    }
}

typedef struct {
    const float *A, *B;
    float *C;
    int n, nc_eff, nib, njb;
    kern_t kern;
    atomic_int next;
} ctx_t;

static float *amalloc(size_t nfloats)
{
    void *p = NULL;
    if (posix_memalign(&p, 64, nfloats * sizeof(float)) != 0) return NULL;
    return (float *)p;
}

static void *worker(void *arg)
{
    ctx_t *x = (ctx_t *)arg;
    const int n = x->n, ncb = x->nc_eff;
    const long ln = n;
    kern_t kern = x->kern;
    float *Ap = amalloc((size_t)MC * KC);
    float *Bp = amalloc((size_t)KC * ncb);
    if (!Ap || !Bp) { free(Ap); free(Bp); abort(); }
    const int total = x->nib * x->njb;

    for (;;) {
        int item = atomic_fetch_add_explicit(&x->next, 1, memory_order_relaxed);
        if (item >= total) break;
        int jb = item / x->nib, ib = item % x->nib;
        int ic = ib * MC, jc = jb * ncb;
        int mc = n - ic < MC ? n - ic : MC;
        int nc = n - jc < ncb ? n - jc : ncb;

        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            int acc = pc > 0;
            pack_b(x->B, ln, pc, jc, kc, nc, Bp);
            pack_a(x->A, ln, ic, pc, mc, kc, Ap);

            for (int jr = 0; jr < nc; jr += NR) {
                int nr = nc - jr < NR ? nc - jr : NR;
                const float *bp = Bp + (long)jr * kc;
                for (int ir = 0; ir < mc; ir += MR) {
                    int mr = mc - ir < MR ? mc - ir : MR;
                    const float *ap = Ap + (long)ir * kc;
                    float *cp = x->C + (long)(ic + ir) * ln + jc + jr;
                    if (mr == MR && nr == NR) {
                        kern(kc, ap, bp, cp, ln, acc);
                    } else {
                        float t[MR * NR];
                        kern(kc, ap, bp, t, NR, 0);
                        for (int i = 0; i < mr; i++) {
                            float *ci = cp + (long)i * ln;
                            const float *ti = t + i * NR;
                            if (acc) for (int j = 0; j < nr; j++) ci[j] += ti[j];
                            else     for (int j = 0; j < nr; j++) ci[j] = ti[j];
                        }
                    }
                }
            }
        }
    }
    free(Ap);
    free(Bp);
    return NULL;
}

static int physical_cores(void)
{
    long online = sysconf(_SC_NPROCESSORS_ONLN);
    if (online < 1) online = 1;
#if defined(__APPLE__)
    int v = 0;
    size_t len = sizeof(v);
    if (sysctlbyname("hw.physicalcpu", &v, &len, NULL, 0) == 0 && v > 0)
        return v;
#elif defined(__linux__)
    int count = 0, ok = 1;
    for (long i = 0; i < online && ok; i++) {
        char path[128];
        snprintf(path, sizeof(path),
                 "/sys/devices/system/cpu/cpu%ld/topology/thread_siblings_list", i);
        FILE *f = fopen(path, "r");
        if (!f) { ok = 0; break; }
        int first = -1;
        if (fscanf(f, "%d", &first) != 1) ok = 0;
        fclose(f);
        if (first == i) count++;
    }
    if (ok && count > 0) return count;
#endif
    return (int)online;
}

static int g_threads = 0;
static kern_t g_kern = NULL;

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    if (!g_kern) g_kern = pick_kernel();
    if (!g_threads) g_threads = physical_cores();

    int nth = g_threads;
    if ((long)n * n * n < 128L * 128 * 128) nth = 1;

    ctx_t x;
    x.A = A; x.B = B; x.C = C; x.n = n; x.kern = g_kern;
    x.nib = (n + MC - 1) / MC;

    /* Shrink the column block when there are too few work items to balance. */
    int ncb = NC;
    while (ncb > 4 * NR && x.nib * ((n + ncb - 1) / ncb) < 3 * nth)
        ncb = ((ncb / 2) + NR - 1) / NR * NR;
    x.nc_eff = ncb;
    x.njb = (n + ncb - 1) / ncb;
    atomic_init(&x.next, 0);

    int total = x.nib * x.njb;
    if (nth > total) nth = total;
    if (nth <= 1) { worker(&x); return; }

    pthread_t *tid = (pthread_t *)malloc(sizeof(pthread_t) * (size_t)(nth - 1));
    int started = 0;
    for (int t = 0; t < nth - 1; t++) {
        if (pthread_create(&tid[t], NULL, worker, &x) != 0) break;
        started++;
    }
    worker(&x);
    for (int t = 0; t < started; t++) pthread_join(tid[t], NULL);
    free(tid);
}
